const D = { density:.55, energy:.7, speed:1, scale:1, hue:220, x:.5, y:.45, twist:.5, style:'night', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const style=P.style;
const night=style==='night', zod=style==='zodiac-gold', aur=style==='aurora-sky', blue=style==='blueprint', mono=style==='mono';
const hue=md(P.hue,360);
const dens=clp(P.density,0,1), en=clp(P.energy,0,1), spd=P.speed, scl=clp(P.scale,.4,2.2);

// ---- seed-dependent value noise (drifting nebula) ----
const sd=P.seed|0;
function hsh(ix,iy){ let h=(ix*374761393+iy*668265263+sd*2147483647)|0; h=(h^(h>>13))*1274126177|0; return ((h^(h>>16))>>>0)/4294967295; }
function vn(x,y){ const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy; const a0=fx*fx*(3-2*fx),b0=fy*fy*(3-2*fy); const a=hsh(ix,iy),b=hsh(ix+1,iy),c=hsh(ix,iy+1),d=hsh(ix+1,iy+1); return a+(b-a)*a0+(c-a)*b0+(a-b-c+d)*a0*b0; }
function fbm(x,y){ return .6*vn(x,y)+.3*vn(x*2.03+5.1,y*2.03-3.2)+.1*vn(x*4.1-2.3,y*4.1+7.7); }

if(S.seedUsed!==P.seed){ S.seedUsed=P.seed; S.o1=fr(1)*30; S.o2=fr(2)*30; }

// coarse nebula buffer (recomputed every frame -> broad real-time motion floor)
const NW=132, NH=Math.max(48,Math.round(NW*Hh/W));
if(!S.nb||S.nw!==NW||S.nh!==NH){ S.nb=createGraphics(NW,NH); S.nb.pixelDensity(1); S.nw=NW; S.nh=NH; }

// per-style nebula palette (deep base -> cloud glow), RGB 0..255
let dR,dG,dB,gR,gG,gB;
if(night){dR=8;dG=16;dB=38; gR=66;gG=122;gB=188;}
else if(zod){dR=26;dG=18;dB=9; gR=158;gG=116;gB=48;}
else if(aur){dR=6;dG=22;dB=26; gR=46;gG=176;gB=134;}
else if(blue){dR=7;dG=18;dB=44; gR=28;gG=84;gB=134;}
else {dR=15;dG=16;dB=20; gR=124;gG=128;gB=144;} // mono

const expo=0.62+en*0.7+K.intensity*0.25+A.rms*0.5;
const drift=K.t*(0.05+spd*0.05);
const swirl=K.t*0.02*spd; const csw=Math.cos(swirl), ssw=Math.sin(swirl);
const nb=S.nb; nb.loadPixels(); const px=nb.pixels;
for(let j=0;j<NH;j++){
  for(let i=0;i<NW;i++){
    let x=(i/NW-0.5)*3.2*(NW/NH), y=(j/NH-0.5)*3.2;
    const rx=x*csw-y*ssw+S.o1+drift*0.6, ry=x*ssw+y*csw+S.o2-drift*0.45;
    let v=fbm(rx,ry);
    v=clp((v-0.22)*1.85,0,1);
    let vv=Math.pow(v,1.05)*expo; if(vv>1.6)vv=1.6;
    const o=4*(j*NW+i);
    px[o]=clp(dR+(gR-dR)*vv,0,255); px[o+1]=clp(dG+(gG-dG)*vv,0,255); px[o+2]=clp(dB+(gB-dB)*vv,0,255); px[o+3]=255;
  }
}
nb.updatePixels();

// ---- stars + constellations (seed + density + style deterministic) ----
const NSTAR=Math.round(110+dens*250);
const key=P.seed+'|'+NSTAR+'|'+style;
if(S.key!==key){
  S.key=key;
  const stars=[];
  for(let s=0;s<NSTAR;s++){
    const mag=Math.pow(fr(s*1.7+3),2.2);
    stars.push({ x:-0.3+fr(s*3.1+1)*1.6, y:-0.3+fr(s*5.7+2)*1.6, mag,
      b:26+74*(1-mag), sz:0.5+2.6*(1-mag),
      tr:0.7+2.6*fr(s*7.3+4), tp:fr(s*2.9+5)*TAU,
      vx:(fr(s*8.1+6)-0.5)*0.018, vy:(fr(s*9.3+7)-0.5)*0.018,
      tmp:fr(s*4.4+8), glow:false });
  }
  const order=stars.map((v,i)=>i).sort((a,b)=>stars[a].mag-stars[b].mag);
  for(let i=0;i<Math.min(24,order.length);i++) stars[order[i]].glow=true;
  const bright=order.slice(0,Math.min(order.length,60));
  const segs=[]; let bi=0; const NCON=8;
  for(let c=0;c<NCON && bi<bright.length;c++){
    const len=3+Math.floor(fr(c*11.1+9)*4);
    let cur=bright[bi++];
    for(let l=1;l<len && bi<bright.length;l++){
      let best=-1,bd=1e9;
      for(let q=bi;q<Math.min(bi+6,bright.length);q++){
        const oo=bright[q]; const dd=Math.hypot(stars[oo].x-stars[cur].x,stars[oo].y-stars[cur].y);
        if(dd<bd){bd=dd;best=q;}
      }
      if(best<0)break;
      const nx=bright[best]; bright[best]=bright[bi]; bright[bi]=nx; bi++;
      segs.push({a:cur,b:nx,c,tp:fr(segs.length*5.3+13)});
      cur=nx;
    }
  }
  S.stars=stars; S.segs=segs; S.nseg=segs.length;
}
const stars=S.stars, segs=S.segs, nseg=S.nseg;

// ---- draw nebula (fills frame; genart owns bg) ----
push();
if(P.alpha<100) tint(0,0,100,P.alpha);
image(nb,0,0,W,Hh);
pop();

// blueprint faint grid overlay
if(blue){
  push(); stroke(198,45,92,7); strokeWeight(0.8);
  const st=u*0.09;
  for(let x=0;x<=W;x+=st) line(x,0,x,Hh);
  for(let y=0;y<=Hh;y+=st) line(0,y,W,y);
  pop();
}

// ---- FAST visible sky rotation + per-star parallax (the motion fix) ----
const rot=K.t*(0.05+P.twist*0.06)*spd;
const cx=P.x*W, cy=P.y*Hh, cs=Math.cos(rot), sn=Math.sin(rot);
const pxs=new Float32Array(stars.length), pys=new Float32Array(stars.length);
for(let s=0;s<stars.length;s++){
  const st=stars[s];
  const bx=(st.x+st.vx*K.t)*W, by=(st.y+st.vy*K.t)*Hh;
  const dx=bx-cx, dy=by-cy;
  pxs[s]=cx+dx*cs-dy*sn; pys[s]=cy+dx*sn+dy*cs;
}

// ---- constellation lines continuously forming / dissolving ----
const activeCon=md(Math.floor(K.section+K.t*0.06),8);
strokeCap(ROUND);
for(let s=0;s<nseg;s++){
  const seg=segs[s];
  const life=md(K.t*0.06*spd + seg.tp + K.section*0.12, 1);
  const f=Math.sin(life*Math.PI);
  if(f<=0.03) continue;
  const ax=pxs[seg.a], ay=pys[seg.a], bx=pxs[seg.b], by=pys[seg.b];
  const active=seg.c===activeCon;
  const gl=(active?1.0:0.55)*(0.5+0.7*en)+(active?K.pulse*0.5+A.mid*0.6:0);
  let lh,ls,lb;
  if(night){ lh=(seg.c%2===0)?190:46; ls=(seg.c%2===0)?45:55; lb=95; }
  else if(zod){ lh=44; ls=60; lb=90; }
  else if(aur){ lh=(seg.c%2===0)?155:180; ls=55; lb=92; }
  else if(blue){ lh=198; ls=55; lb=96; }
  else { lh=0; ls=0; lb=92; }
  stroke(lh,ls,lb, clp(42*f*gl,0,90));
  strokeWeight(u*(active?0.0026:0.0016)*scl);
  if(blue){
    const dl=Math.hypot(bx-ax,by-ay), n=Math.max(2,Math.floor(dl/9));
    for(let d=0;d<n;d+=2){ const t0=d/n,t1=Math.min(1,(d+1)/n); line(ax+(bx-ax)*t0,ay+(by-ay)*t0, ax+(bx-ax)*t1,ay+(by-ay)*t1); }
  } else line(ax,ay,bx,by);
}

// ---- stars (twinkle) ----
noStroke();
const twG=0.6+0.8*en;
for(let s=0;s<stars.length;s++){
  const st=stars[s]; const x=pxs[s], y=pys[s];
  if(x<-6||x>W+6||y<-6||y>Hh+6) continue;
  const tw=0.58+0.42*Math.sin(K.t*st.tr*spd+st.tp);
  const b=clp(st.b*tw*twG,0,100);
  const sz=st.sz*u*0.0034*scl*(0.8+0.5*tw);
  let sh,ss;
  if(zod){ sh=44; ss=st.mag<0.25?18:36; }
  else if(aur){ sh=st.mag<0.3?175:160; ss=st.mag<0.25?20:45; }
  else if(blue){ sh=198; ss=40; }
  else if(mono){ sh=0; ss=0; }
  else { sh=md(hue+(st.mag<0.3?4:12),360); ss=st.mag<0.22?12:6; }
  if(blue){
    stroke(198,45,96,clp(b,15,80)); strokeWeight(u*0.0013); noFill(); circle(x,y,sz*2.0);
    if(st.glow){ noStroke(); fill(198,25,100,b); circle(x,y,sz*0.9); } noStroke();
  } else {
    if(st.glow){ drawingContext.shadowBlur=sz*3.6; drawingContext.shadowColor=(night||mono)?'rgba(190,215,255,0.9)':(zod?'rgba(255,220,150,0.9)':'rgba(150,255,220,0.9)'); }
    fill(sh,ss,b); circle(x,y,sz);
    drawingContext.shadowBlur=0;
  }
}
drawingContext.shadowBlur=0;

// ---- frequent shooting stars (multiple generators, spawn on K.t) ----
const NSH=4;
blendMode(ADD);
for(let k=0;k<NSH;k++){
  const period=3.0+fr(k*13.1+70)*3.0;
  const off=fr(k*7.7+71);
  const ph=md(K.t/period+off,1);
  if(ph<0.14){
    const kk=ph/0.14; const si=Math.floor(K.t/period+off);
    const sx=fr(si*3.7+41+k)*W, sy=fr(si*1.9+42+k)*Hh*0.6;
    const ang=(-0.4+0.8*fr(si*5.3+43+k))+Math.PI*0.16;
    const len=u*(0.18+0.1*fr(si*2.2+44+k));
    const hx=sx+Math.cos(ang)*len*kk, hy=sy+Math.sin(ang)*len*kk;
    const tx=hx-Math.cos(ang)*len*0.55, ty=hy-Math.sin(ang)*len*0.55;
    const fade=Math.sin(kk*Math.PI);
    const shh=zod?44:aur?165:blue?198:md(hue+24,360);
    stroke(shh,zod?30:20,100,72*fade); strokeWeight(u*0.0032*scl); line(tx,ty,hx,hy);
    noStroke(); fill(0,0,100,88*fade); circle(hx,hy,u*0.011*(0.5+fade));
  }
}
blendMode(BLEND);

// ---- audio treble shimmer (partial, never full-frame) ----
if((A.treble>0.02||A.rms>0.02)){
  push(); blendMode(ADD); noStroke();
  const glow=(A.treble*0.5+A.rms*0.4)*en;
  fill(md(hue+30,360),25,100,glow*18);
  rect(0,0,W,Hh);
  blendMode(BLEND); pop();
}
drawingContext.shadowBlur=0;
blendMode(BLEND);
